// The report uses the exact successful simulation request AND that route's matching
// report API. Reserve the popup during user activation; use a download fallback if
// the browser blocks it. A new scenario invalidates the pending report.
async function openReport(b, report, stillCurrent) {
    if (!report || !stillCurrent()) {
        b.disabled = true;
        return;
    }
    let popup = null;
    try {
        popup = window.open("about:blank", "_blank");
        if (popup)
            popup.opener = null;
    }
    catch { /* use download fallback */ }
    b.disabled = true;
    const r = await api(report.path, { method: "POST", body: report.body, as: "text", timeoutMs: 15000 });
    if (!stillCurrent()) {
        popup?.close();
        return;
    }
    b.disabled = false;
    if (!r.ok) {
        popup?.close();
        b.title = t("cockpit.report.fail", { e: r.error });
        b.textContent = t("cockpit.report.failShort");
        return;
    }
    const url = URL.createObjectURL(new Blob([r.data], { type: "text/html" }));
    if (popup && !popup.closed)
        popup.location.replace(url);
    else
        Object.assign(document.createElement("a"), { href: url, download: "braspace-mission-report.html" }).click();
    setTimeout(() => URL.revokeObjectURL(url), 60000);
}
document.getElementById("report")?.addEventListener("click", e => {
    const report = S.report;
    return openReport(e.currentTarget, report, () => S.report === report);
});
