    c.append(sum);
    const form = document.createElement("form");
    form.className = "ck-crew-form";
    form.noValidate = true;
    const elems = form.elements;
    const field = (k, v, step) => {
        const l = document.createElement("label");
        l.textContent = t("crew.f." + k);
        const i = document.createElement("input");
        i.type = "number";
        i.min = "0";
        i.step = step;
        i.value = String(v);
        i.name = k;
        i.inputMode = "decimal";
        l.append(i);
        form.append(l);
    };
    for (const k of POWER_FIELDS)
        field(k, ({ ...H1_PROFILE, reserve_wh: 4000 })[k], "1");
    for (const k of CREW_FIELDS)
        field(k, CREW_DEFAULT[k], k === "size" ? "1" : "0.01");
    const go = document.createElement("button");
    go.type = "submit";
    go.className = "mp-pill is-primary";
    go.textContent = t("crew.run");
    form.append(go);
    const out = document.createElement("div");
    out.className = "ck-crew-out";
    out.setAttribute("aria-live", "polite");
    const src = document.createElement("p");
    src.className = "mp-label";
    src.textContent = t("crew.src", { s: CREW_DEFAULT.rate_source });
    const tools = document.createElement("div");
    tools.className = "ck-crew-tools";
    const bSens = document.createElement("button");
    bSens.type = "button";
    bSens.className = "mp-pill";
    bSens.textContent = t("crew.sens");
    const bSave = document.createElement("button");
    bSave.type = "button";
    bSave.className = "mp-pill";
    bSave.textContent = t("crew.save");
    const bExp = document.createElement("button");
    bExp.type = "button";
    bExp.className = "mp-pill";
    bExp.textContent = t("crew.export");
    const bReport = document.createElement("button");
    bReport.type = "button";
    bReport.className = "mp-pill";
    bReport.textContent = t("crew.report");
